raw_input.content:
#!/usr/bin/env python3
import urllib.request
import json
import sys

headers = {"User-Agent": "Mozilla/5.0"}

queries = [
    ("SGLang releases", "https://api.github.com/repos/sgl-project/sglang/releases?per_page=5"),
    ("vLLM releases", "https://api.github.com/repos/vllm-project/vllm/releases?per_page=5"),
    ("SGLang stars", "https://api.github.com/repos/sgl-project/sglang"),
    ("vLLM stars", "https://api.github.com/repos/vllm-project/vllm"),
    ("SGLang MoE PRs", "https://api.github.com/search/issues?q=repo:sgl-project/sglang+MoE+in:title+type:pr&per_page=5"),
    ("vLLM MoE PRs", "https://api.github.com/search/issues?q=repo:vllm-project/vllm+MoE+in:title+type:pr&per_page=5"),
    ("SGLang DeepSeek", "https://api.github.com/search/issues?q=repo:sgl-project/sglang+DeepSeek+in:title&type:pr&per_page=5"),
    ("vLLM DeepSeek", "https://api.github.com/search/issues?q=repo:vllm-project/vllm+DeepSeek+in:title&type:pr&per_page=5"),
]

for name, url in queries:
    try:
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode())
            if "tag_name" in data:
                print(f"\n=== {name} ===")
                print(f"  tag: {data['tag_name']}, published: {data.get('published_at','')}")
            elif "items" in data:
                print(f"\n=== {name} ===")
                for item in data["items"]:
                    print(f"  {item['title']}")
                    print(f"  {item['html_url']}")
            elif "full_name" in data:
                print(f"\n=== {name} ===")
                print(f"  stars: {data.get('stargazers_count','')}, forks: {data.get('forks_count','')}")
                print(f"  description: {data.get('description','')}")
            else:
                print(f"\n=== {name} === (unexpected format)")
    except Exception as e:
        print(f"\n=== {name} === ERROR: {e}")

